window.TP3B["camara:220621"] = [{"t":"PEC","n":"8","y":"2026","e":"Altera o art. 228 da Constituição Federal para admitir, em caráter excepcional, a redução da maioridade penal em casos de crimes hediondos e de crueldade extrema contra pessoas e animais.","d":"2026-05-11","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-08-12","ds":"Designado Relator, Dep. Mendonça Filho (PL-PE), para a PEC 32/2015, ao qual esta proposição está apensada.","id":"2623400","law":false,"r":"c"},{"t":"PDL","n":"255","y":"2026","e":"Susta a eficácia do inciso XL do Art. 9°-C do Anexo XXI da Portaria de Consolidação GM/MS n° 2, de 28 de setembro de 2017, incluído pela Portaria GM/MS n° 10.719, de 7 de abril de 2026, que dispõe sobre a composição do Comitê Técnico Nacional de Saúde LGBTIA+.","d":"2026-04-22","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2026-04-22","ds":"Apresentação do PDL n. 255/2026 (Projeto de Decreto Legislativo de Sustação de Atos Normativos do Poder Executivo), pelas Deputada Rosangela Moro (PL/SP) e outros, que \"Susta a eficácia do inciso XL do Art. 9°-C do Anexo XXI da Portaria de Consolidação GM/MS n° 2, de 28 de setembro de 2017, incluído pela Portaria GM/MS n° 10.719, de 7 de abril de 2026, que dispõe sobre a composição do Comitê Técni","id":"2617450","law":false,"r":"c"},{"t":"PLP","n":"54","y":"2026","e":"Regulamenta a aplicação do art. 42, § 3º, da Constituição Federal, introduzido pela Emenda Constitucional nº 101, de 2019, dispondo sobre a acumulação de cargos pelos militares dos Estados, do Distrito Federal e dos Territórios.","d":"2026-03-11","o":"status_not_published","s":"","tr":"Apresentação de Proposição","u":"2026-03-11","ds":"Apresentação do PLP n. 54/2026 (Projeto de Lei Complementar), pelo Deputado Sargento Gonçalves (PL/RN), que \"Regulamenta a aplicação do art. 42, § 3º, da Constituição Federal, introduzido pela Emenda Constitucional nº 101, de 2019, dispondo sobre a acumulação de cargos pelos militares dos Estados, do Distrito Federal e dos Territórios. \n\".","id":"2608432","law":false,"r":"m"},{"t":"PL","n":"824","y":"2026","e":"Dispõe sobre a proteção dos direitos fundamentais das mulheres, das crianças e das minorias, bem como da vedação à promoção e aplicação do conjunto de normas e práticas que compõe o que é conhecido como lei da Sharia no território nacional.","d":"2026-03-02","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Notificações","u":"2026-07-07","ds":"Deferido o Requerimento n. 2583/2026.","id":"2605433","law":false,"r":"c"},{"t":"PL","n":"806","y":"2026","e":"Altera a Lei nº 10.779, de 25 de novembro de 2003, para dispor sobre a correspondência entre o período de paralisação obrigatória da atividade pesqueira e a duração do Seguro-Desemprego do Pescador Artesanal, instituir o Cadastro Nacional de Pescadores e Marisqueiras e estabelecer sanções por fraude contra programas governamentais","d":"2026-02-27","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-06-16","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 01/06/2026 a 16/06/2026). Não foram apresentadas emendas ao substitutivo.","id":"2605323","law":false,"r":"c"},{"t":"PL","n":"595","y":"2026","e":"Estabelece normas gerais de responsabilidade, transitoriedade e emancipação produtiva aplicáveis aos programas federais de transferência de renda e auxílios sociais.","d":"2026-02-19","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-03-24","ds":"Recebimento pelo(a) CASP.","id":"2603433","law":false,"r":"m"},{"t":"PL","n":"477","y":"2026","e":"Institui diretrizes nacionais de valorização do Motoclubismo social e cultural, reconhece os Moto Clubes como organizações privadas de relevante valor social e dá outras providências.","d":"2026-02-11","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-03-19","ds":"Recebimento pelo(a) CTUR.","id":"2602509","law":false,"r":"m"},{"t":"PL","n":"6544","y":"2025","e":"Revoga os artigos 359-L e 359-M do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), introduzidos pela Lei nº 14.197, de 1º de setembro de 2021, que tratam dos crimes de abolição violenta do Estado Democrático de Direito e de golpe de Estado, a fim de assegurar a observância dos princípios constitucionais da liberdade de expressão, do direito de reunião e da segurança jurídica.","d":"2025-12-18","o":"status_not_published","s":"","tr":"Publicação de Proposição","u":"2026-04-06","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 07/04/2026.","id":"2598538","law":false,"r":"m"},{"t":"PEC","n":"48","y":"2025","e":"Altera o inciso XVI do art. 37 da Constituição Federal para permitir a acumulação de cargos públicos por outros profissionais da área da educação.","d":"2025-12-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2025-12-11","ds":"Apresentação do REQ n. 5740/2025 (Requerimento de Inclusão ou Retirada de Assinatura em Proposição de Iniciativa Coletiva Obrigatória), pelo Deputado Junior Lourenço (PL/MA), que \"Requer a inclusão de assinatura na Proposta de Emenda à Constituição nº 48, de 2025, que Altera o inciso XVI do art. 37 da Constituição Federal para permitir a acumulação de cargos públicos por outros profissionais da ár","id":"2595818","law":false,"r":"c"},{"t":"PL","n":"5592","y":"2025","e":"Dispõe sobre a criação da Rota Turística das Serras do Agreste Potiguar e Paraibano, e dá outras providências.","d":"2025-11-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-12-03","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 04/12/2025 PÁG 870.","id":"2580095","law":false,"r":"m"},{"t":"PL","n":"5584","y":"2025","e":"Altera a Lei nº 13.756, de 12 de dezembro de 2018, para destinar parte dos recursos do Fundo Nacional de Segurança Pública à assistência jurídica de operadores de segurança pública processados por atos decorrentes do exercício da função.","d":"2025-11-03","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2026-05-11","ds":"Recebimento pela CFT.","id":"2579897","law":false,"r":"m"},{"t":"PEC","n":"40","y":"2025","e":"Altera o Art. 7° da Constituição Federal para prever a possibilidade de opção pelos empregados quanto à jornada de trabalho, podendo escolher entre o regime comum previsto pela Consolidação das Leis do Trabalho (CLT), ou um regime flexível baseado em horas trabalhadas.","d":"2025-10-29","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Requerimento","u":"2026-02-25","ds":"Apresentação do REQ n. 3/2026 (Requerimento de Audiência Pública), pelo Deputado Domingos Sávio (PL/MG), que \"Requer realização de audiência pública acerca da redução da jornada de trabalho, conforme proposta nas PECs nº 40/2025 e nº 8/2025\".","id":"2578996","law":false,"r":"c"},{"t":"PL","n":"5427","y":"2025","e":"Acrescenta inciso ao art. 6º da Lei nº 10.826, de 22 de dezembro de 2003, para conceder porte de arma de fogo aos diretores de clubes de tiro desportivo e aos proprietários ou responsáveis legais por estabelecimentos de comércio de armas de fogo, munições e acessórios.","d":"2025-10-27","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-03-30","ds":"Encaminhada à publicação. Parecer da Comissão de Segurança Pública e Combate ao Crime Organizado Publicado em avulso e no DCD de 31/03/2026, Letra A.","id":"2576644","law":false,"r":"m"},{"t":"PL","n":"5024","y":"2025","e":"Altera o art. 18 da Lei nº 14.751, de 12 de dezembro de 2023, para assegurar aos militares estaduais o direito ao cumprimento de pena de prisão em unidade prisional militar.","d":"2025-10-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-06-19","ds":"Encaminhada à publicação. Parecer da Comissão de Segurança Pública e Combate ao Crime Organizado Publicado em avulso e no DCD de 20/06/2026, Letra A.","id":"2569118","law":false,"r":"m"},{"t":"PEC","n":"35","y":"2025","e":"Altera a Constituição Federal para acrescentar os §§ 4º e 5º ao art. 164 para determinar que a criação, emissão e circulação de qualquer moeda digital do Banco Central (CBDC) ou outro ativo digital requer aprovação das duas Casas do Congresso Nacional, bem como para determinar que a extinção do papel-moeda forçada no território nacional é vedada, salvo se aprovada em cada uma das duas Casas do Congresso Nacional.","d":"2025-09-23","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2025-09-23","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2563273","law":false,"r":"c"},{"t":"PL","n":"4352","y":"2025","e":"Altera a Lei nº 14.751, de 12 de dezembro de 2023, para dispor sobre a estrutura organizacional e a progressão na carreira das Polícias Militares e dos Corpos de Bombeiros Militares.","d":"2025-09-01","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2025-09-01","ds":"Apresentação do PL n. 4352/2025 (Projeto de Lei), pelo Deputado Sargento Gonçalves (PL/RN), que \"Altera a Lei nº 14.751, de 12 de dezembro de 2023, para dispor sobre a estrutura organizacional e a progressão na carreira das Polícias Militares e dos Corpos de Bombeiros Militares\".","id":"2555397","law":false,"r":"m"},{"t":"PL","n":"4213","y":"2025","e":"Altera o Decreto-Lei nº 2.848, de 07 de dezembro de 1940 (Código Penal), para tipificar o crime de fuga de blitz com direção perigosa.","d":"2025-08-26","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2025-12-22","ds":"Apensação da proposição PL-5290/2025 à proposição PL-4213/2025.","id":"2552428","law":false,"r":"m"},{"t":"PL","n":"4068","y":"2025","e":"Institui o Cadastro Nacional de Torcedores Violentos (CNTV), estabelece normas para a restrição de acesso a eventos esportivos e dá outras providências.","d":"2025-08-18","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2026-03-20","ds":"Encaminhada à publicação. Parecer da Comissão do Esporte Publicado em avulso e no DCD de 21/03/2026, Letra B.","id":"2549046","law":false,"r":"m"},{"t":"PL","n":"4031","y":"2025","e":"Altera o Decreto-Lei nº 1.001, de 1969 (Código Penal Militar), para tipificar o crime de assédio moral nas instituições militares, estabelecer causas de aumento de pena e prever hipóteses de exclusão de ilicitude.","d":"2025-08-15","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apensação","u":"2025-10-10","ds":"Apensação desta proposição ao PL 4752/2024.","id":"2547153","law":false,"r":"m"},{"t":"PL","n":"4016","y":"2025","e":"Altera o art. 15 da Lei nº 14.751, de 12 de dezembro de 2023, para permitir a ascensão dos oficiais do Quadro de Oficiais Especialistas (QOE) até o posto de coronel.","d":"2025-08-15","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2025-08-15","ds":"Apresentação do PL n. 4016/2025 (Projeto de Lei), pelo Deputado Sargento Gonçalves (PL/RN), que \"Altera o art. 15 da Lei nº 14.751, de 12 de dezembro de 2023, para permitir a ascensão dos oficiais do Quadro de Oficiais Especialistas (QOE) até o posto de coronel\".","id":"2545961","law":false,"r":"m"},{"t":"PL","n":"3798","y":"2025","e":"Dispõe sobre vedações à atuação de magistrados no exercício da função jurisdicional, com o objetivo de preservar os princípios constitucionais do devido processo legal, imparcialidade, juiz natural, liberdade de expressão e separação de Poderes.","d":"2025-08-06","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Autorização)","tr":"Apresentação de Proposição","u":"2025-08-06","ds":"Apresentação do PL n. 3798/2025 (Projeto de Lei), pelos Deputado Rodrigo da Zaeli (PL/MT) e outros, que \"Dispõe sobre vedações à atuação de magistrados no exercício da função jurisdicional, com o objetivo de preservar os princípios constitucionais do devido processo legal, imparcialidade, juiz natural, liberdade de expressão e separação de Poderes\n\".","id":"2541173","law":false,"r":"c"},{"t":"PL","n":"3681","y":"2025","e":"Dispõe sobre a aplicação de sanções administrativas e restrições a indivíduos, nacionais ou estrangeiros, responsáveis por crimes graves, incluindo tortura, tráfico de drogas, corrupção, violação de direitos humanos, entre outros, e dá outras providências.","d":"2025-08-04","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2025-09-02","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 03/09/2025.","id":"2539268","law":false,"r":"c"},{"t":"PL","n":"3622","y":"2025","e":"Extingue a cobrança do Imposto sobre Operações de Crédito, Câmbio e Seguro, ou relativas a Títulos ou Valores Mobiliários – IOF, por meio da revogação de sua disciplina infraconstitucional.","d":"2025-07-21","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-10-01","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 02/10/2025.","id":"2538430","law":false,"r":"c"},{"t":"PDL","n":"506","y":"2025","e":"Susta os efeitos do Decreto nº 12.551, de 14 de julho de 2025, que regulamenta a Lei nº 15.122, de 11 de abril de 2025 (Lei de Reciprocidade Econômica), que “Estabelece critérios para suspensão de concessões comerciais, de investimentos e de obrigações relativas a direitos de propriedade intelectual em resposta a medidas unilaterais adotadas por país ou bloco econômico que impactem negativamente a competitividade internacional brasileira; e dá outras providências”.","d":"2025-07-16","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Apresentação de Proposição","u":"2025-07-16","ds":"Apresentação do PDL n. 506/2025 (Projeto de Decreto Legislativo), pelas Deputada Rosangela Moro (UNIÃO/SP) e outros, que \"Susta os efeitos do Decreto nº 12.551, de 14 de julho de 2025, que regulamenta a Lei nº 15.122, de 11 de abril de 2025 (Lei de Reciprocidade Econômica), que “Estabelece critérios para suspensão de concessões comerciais, de investimentos e de obrigações relativas a direitos de p","id":"2537338","law":false,"r":"c"},{"t":"PL","n":"2433","y":"2025","e":"Institui a Semana Nacional da Cultura Evangélica.","d":"2025-05-21","o":"in_progress","s":"Pronta para Pauta","tr":"Designação de Relator(a)","u":"2026-04-22","ds":"Designado Relator, Dep. Diego Garcia (REPUBLIC-PR).","id":"2514763","law":false,"r":"m"},{"t":"PL","n":"2231","y":"2025","e":"Revoga os artigos 359-L e 359-M do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), introduzidos pela Lei nº 14.197, de 1º de setembro de 2021, que tratam dos crimes de abolição violenta do Estado Democrático de Direito e de tentativa de deposição, por meio de violência ou grave ameaça, do governo legitimamente constituído, a fim de assegurar a observância dos princípios constitucionais da liberdade de expressão, do direito de reunião e da segurança jurídica.","d":"2025-05-12","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-12-09","ds":"Desapensação deste do PL nº 2.162, de 2023, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial. (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão)","id":"2507260","law":false,"r":"m"},{"t":"PL","n":"1813","y":"2025","e":"Altera a Lei nº 8.213, de 24 de julho de 1991, para vedar o desconto de mensalidades associativas, contribuições a entidades de classe ou quaisquer valores destinados a organizações similares nos benefícios previdenciários, ainda que mediante autorização do beneficiário.","d":"2025-04-23","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-09-03","ds":"Desapensação deste do PL nº 1.546, de 2024, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 1.546, de 2024, adotado pelo relator da Comissão Especial. (Sessão Deliberativa Extraordinária Presencial de 03/09/2025 - 13:55 - 175ª Sessão)","id":"2499849","law":false,"r":"c"},{"t":"PEC","n":"17","y":"2025","e":"Acrescenta os §§ 11, 12 e 13 ao art. 144 da Constituição Federal, para instituir o piso salarial dos servidores policiais civis e militares e bombeiros militares.","d":"2025-04-23","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2025-04-23","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2499794","law":false,"r":"c"},{"t":"PL","n":"1784","y":"2025","e":"Dispõe sobre a imutabilidade do registro de sexo biológico nas certidões de nascimento e casamento e dá outras providências.","d":"2025-04-22","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-02-25","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 19/12/2025 a 25/02/2026). Não foram apresentadas emendas.","id":"2498918","law":false,"r":"c"},{"t":"PL","n":"1665","y":"2025","e":"Altera a Lei nº 9.503, de 23 de setembro de 1997 (Código de Trânsito Brasileiro), para permitir a destinação de percentual das multas de trânsito aplicadas por integrantes das Polícias Militares às ações de policiamento ostensivo e fiscalização viária, e dá outras providências.","d":"2025-04-11","o":"in_progress","s":"Aguardando Parecer","tr":"Apresentação de Requerimento","u":"2026-04-14","ds":"Apresentação do REQ n. 2058/2026 (Requerimento de Apensação), pelo Deputado Aureo Ribeiro (SOLIDARI/RJ), que \"Requer a apensação de proposições que tratam de alterações na Lei nº 9.503, de 23 de setembro de 1997, Código de Trânsito Brasileiro, ao PL nº 8.085/2014, por versarem sobre matérias correlatas\".","id":"2497357","law":false,"r":"m"},{"t":"PDL","n":"143","y":"2025","e":"Susta os efeitos da Orientação Normativa nº 94, de 2025, que tenta institucionalizar atuação do cônjuge presidencial como agente público simbólico, sem previsão constitucional ou legal.","d":"2025-04-08","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-10-08","ds":"Recebimento pelo(a) CASP.","id":"2495579","law":false,"r":"c"},{"t":"PDL","n":"139","y":"2025","e":"Susta a Portaria MJSP nº 911, de 27 de março de 2025.","d":"2025-03-28","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2025-12-19","ds":"Designada Relatora, Dep. Erika Hilton (PSOL-SP).","id":"2490884","law":false,"r":"c"},{"t":"PL","n":"943","y":"2025","e":"Dispõe sobre a criação da Rota Turística da Serra de João do Vale, nos estados do Rio Grande do Norte e da Paraíba, e dá outras providências.","d":"2025-03-12","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2025-08-21","ds":"Encaminhada à publicação. Parecer da Comissão de Turismo Publicado em avulso e no DCD de 22/08/2025, Letra A.","id":"2486687","law":false,"r":"m"},{"t":"PL","n":"896","y":"2025","e":"Dispõe sobre a pontuação do tempo de serviço prestado nas instituições previstas no artigo 144 da Constituição Federal como título em concursos públicos para os órgãos de segurança pública.","d":"2025-03-11","o":"status_not_published","s":"","tr":"Notificacao para Publicação Intermediária","u":"2026-05-12","ds":"Designado Relator, Dep. Capitão Alden (PL-BA), para o PL 3507/2024, ao qual esta proposição está apensada.","id":"2486476","law":false,"r":"m"},{"t":"PL","n":"736","y":"2025","e":"Altera a Lei nº 12.977, de 20 de maio de 2014, para dispor sobre o aprimoramento da rastreabilidade, fiscalização e penalização de estabelecimentos de desmontagem de veículos.","d":"2025-02-28","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-05-28","ds":"Recebimento pela CCJC.","id":"2485849","law":false,"r":"m"},{"t":"PL","n":"243","y":"2025","e":"Altera as Leis nºs 14.133, de 1º de abril de 2021 (Lei de Licitações), 8.069, de 13 de julho de 1990 (Estatuto da Criança e do Adolescente), e 8.313, de 23 de dezembro de 1991 (Institui Pronac), para estabelecer medidas de combate ao incentivo e à apologia ao consumo de drogas, ao crime organizado e à prática de condutas criminosas em eventos de qualquer natureza contratados ou incentivados pelos Governos Federal, Estadual e Municipal, bem como estabelecer o crime de exposição de crianças e adolescentes a esses tipos de conteúdos.","d":"2025-02-04","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-06-20","ds":"Parecer da Relatora, Dep. Chris Tonietto (PL-RJ), pela aprovação, com emenda.","id":"2482843","law":false,"r":"c"},{"t":"PL","n":"10","y":"2025","e":"Dispõe sobre a criminalização de condutas atentatórias contra o Cristianismo e estabelece a reparação por dano moral objetivo à imagem do Cristianismo em caso de ofensa pública às religiões de matriz cristã, e dá outras providências.","d":"2025-02-03","o":"status_not_published","s":"","tr":"Notificações","u":"2025-11-10","ds":"Devolvido ao Relator, Dep. Pr. Marco Feliciano (PL-SP), para o PL 1804/2015, ao qual esta proposição está apensada.","id":"2482103","law":false,"r":"c"},{"t":"PL","n":"4618","y":"2024","e":"Altera a redação do artigo 6º da Lei 10.826, de 2003, para autorizar agentes de segurança pública, ativos e inativos, previstos no artigo 144 da Constituição Federal e guardas municipais, a adquirir até seis armas de fogo de uso restrito ou permitido e suas munições.","d":"2024-11-30","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2026-05-04","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 17/04/2026 a 04/05/2026). Não foram apresentadas emendas.","id":"2473516","law":false,"r":"m"},{"t":"PEC","n":"42","y":"2024","e":"Acrescenta o inciso VI ao art. 51 da Constituição Federal, para estabelecer competência privativa à Câmara dos Deputados relativa à fiscalização das atividades das agências reguladoras.","d":"2024-11-11","o":"in_progress","s":"Aguardando Criação de Comissão Temporária","tr":"Publicação de Proposição","u":"2025-10-27","ds":"Encaminhada à publicação. Parecer da Comissão de Constituição e Justiça e de Cidadania Publicado em avulso e no DCD de 28/10/2025, Letra A.","id":"2467670","law":false,"r":"c"},{"t":"PL","n":"4302","y":"2024","e":"Altera a Lei nº 10.826, de 22 de dezembro de 2003, para regulamentar o porte de arma pelos integrantes dos órgãos operacionais do Sistema Único de Segurança Pública e dá outras providências.","d":"2024-11-09","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2025-03-14","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 15/03/2025 PAG 51","id":"2467640","law":false,"r":"m"},{"t":"PEC","n":"29","y":"2024","e":"Altera a Constituição Federal para acrescentar no art. 5º texto sobre o marco temporal de início da vida humana explicitando de forma inequívoca a inviolabilidade do direito à vida, desde a sua concepção, bem como cria o inciso LXXX para especificar que a concepção é a junção do gameta masculino e o feminino, ocorrida durante a fecundação, em local propício para o desenvolvimento celular.","d":"2024-07-10","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2024-07-10","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2448752","law":false,"r":"c"},{"t":"PL","n":"2786","y":"2024","e":"Institui o Dia Nacional dos Presos Políticos.","d":"2024-07-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Notificações","u":"2024-10-16","ds":"Deferido o Requerimento nº 3819/2024.","id":"2447559","law":false,"r":"c"},{"t":"PL","n":"2499","y":"2024","e":"Dispõe sobre a obrigatoriedade da notificação à autoridade policial, pelos hospitais, clínicas e unidades básicas de saúde, da interrupção de gestação decorrente de estupro e dá outras providências.","d":"2024-06-19","o":"in_progress","s":"Aguardando Parecer","tr":"Encerramento de Prazo","u":"2024-09-18","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao projeto (de 30/08/2024 a 18/09/2024). Não foram apresentadas emendas.","id":"2442393","law":false,"r":"c"},{"t":"PL","n":"2479","y":"2024","e":"Altera as Leis 11.340, de 07 de agosto de 2006, e 10.826, de 22 de dezembro de 2003, para autorizar o porte de arma de fogo às mulheres em situação de violência doméstica e amparadas por medidas protetivas.","d":"2024-06-19","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-04-23","ds":"Apensação do PL 1080/2026 a esta proposição.","id":"2441956","law":false,"r":"m"},{"t":"PL","n":"2388","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal) e a Lei nº 7.210, de 11 de julho de 1984 (Lei de Execução Penal), para estabelecer punições mais severas aos crimes de estupro e estupro de vulnerável.","d":"2024-06-13","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-05-26","ds":"Apense-se a este o PL 1682/2026","id":"2440784","law":false,"r":"c"},{"t":"PL","n":"2058","y":"2024","e":"Cria a Lei de Criminalização do Revenge Porn e Sextorsão.","d":"2024-05-27","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2025-10-08","ds":"Recebimento pela CCJC.","id":"2436529","law":false,"r":"c"},{"t":"PL","n":"1904","y":"2024","e":"Acresce dois parágrafos ao art. 124, um parágrafo único ao artigo 125, um segundo parágrafo ao artigo 126 e um parágrafo único ao artigo 128, todos do Código Penal Brasileiro, e dá outras providências.","d":"2024-05-17","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Aprovação de Requerimento","u":"2024-08-14","ds":"Aprovado o requerimento nº 44/2024,da Sra. Chris Tonietto que requer a realização de Audiência Pública para debater sobre o PL 1904/2024, que acresce dois parágrafos ao art. 124, um parágrafo único ao artigo 125, um segundo parágrafo ao artigo 126 e um parágrafo único ao artigo 128, todos do Código Penal Brasileiro, e dá outras providências.","id":"2434493","law":false,"r":"c"},{"t":"PL","n":"1633","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal para considerar como crime a criação de óbice ou embaraço fiscal, sanitário, ambiental ou administrativo, oimpedimento ou dificuldade ao serviço de combate ao perigo, de socorro ou salvamento, ou a entregade donativos ou o resgate às vítimas, durante a vigência de estado de calamidade pública.","d":"2024-05-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Recebimento","u":"2024-05-13","ds":"Recebimento pela CCJC.","id":"2431790","law":false,"r":"c"},{"t":"PL","n":"1502","y":"2024","e":"Altera a Lei nº 7.102, de 20 de junho de 1983, para garantir o uso de coletes de proteção balística nível III-A por vigilantes e expandir a lista de equipamentos permitidos durante a prestação de serviço de vigilância.","d":"2024-04-30","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2024-05-07","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 08/05/2024.","id":"2430585","law":false,"r":"m"},{"t":"PL","n":"1360","y":"2024","e":"Dispõe sobre a inclusão obrigatória do tema \"Transtorno do Espectro Autista (TEA)\" nas grades curriculares dos cursos de graduação nas áreas de Saúde e Educação e estabelece as diretrizes para sua implementação.","d":"2024-04-19","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-12-10","ds":"Recebimento pela CCJC, apensado ao PL-1462/2022","id":"2428398","law":false,"r":"m"},{"t":"PL","n":"1116","y":"2024","e":"Altera a Lei nº 1.579, de 18 de março de 1952, que dispõe sobre as Comissões Parlamentares de Inquérito, para possibilitar o acompanhamento das providências adotadas após o encerramento dos trabalhos.","d":"2024-04-08","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-07-08","ds":"Parecer com Complementação de Voto, Dep. Chris Tonietto (PL-RJ), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação, com substitutivo.","id":"2424865","law":false,"r":"c"},{"t":"PDL","n":"108","y":"2024","e":"Susta parcialmente os efeitos da Resolução n. 391, de 10 de maio de 2021, do Conselho Nacional de Justiça, que \"estabelece procedimentos e diretrizes a serem observados pelo Poder Judiciário para o reconhecimento do direito à remição de pena por meio de práticas sociais educativas em unidades de privação de liberdade\".","d":"2024-04-02","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-04-19","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 20/04/2024.","id":"2424406","law":false,"r":"c"},{"t":"PL","n":"1020","y":"2024","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), para reformular o crime de receptação, adequando as penas à gravidade dos crimes originários dos bens receptados.","d":"2024-03-27","o":"status_not_published","s":"","tr":"Notificacao para Publicação Intermediária","u":"2026-05-11","ds":"Designado Relator, Dep. Marangoni (PODE-SP), para o PL 770/2015, ao qual esta proposição está apensada.","id":"2423996","law":false,"r":"m"},{"t":"PDL","n":"30","y":"2024","e":"Susta, parcialmente, a Resolução 23.732 de 27 de fevereiro de 2024 do Tribunal Superior Eleitoral, que dispõe sobre propaganda eleitoral, utilização e geração do horário gratuito e condutas ilícitas em campanha eleitoral, especificamente os artigos 9º-D, 9º-E, 9º-F e 9ª-H incluídos pelo art. 1º da Resolução.","d":"2024-03-05","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-21","ds":"Recebimento pela CCJC, apensado ao PDL-25/2024","id":"2419264","law":false,"r":"c"},{"t":"PL","n":"254","y":"2024","e":"Altera a Lei nº 8.313, de 23 de dezembro de 1991, para incluir restrições à aprovação de projetos culturais que atentem contra a honra e a imagem das forças policiais, promovam a promiscuidade, afrontem a família, os valores religiosos, a sexualização infantil, ou promovam outras condutas socialmente reprováveis.","d":"2024-02-15","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-05-25","ds":"Designada Relatora, Dep. Delegada Ione (PL-MG), para o PL 5941/2013, ao qual esta proposição está apensada.","id":"2417912","law":false,"r":"m"},{"t":"PL","n":"249","y":"2024","e":"Altera os arts. 121 e 129 do Decreto-Lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), e o art. 1º da Lei nº 8.072, de 25 de julho de 1990 (Lei de Crimes Hediondos).","d":"2024-02-09","o":"in_progress","s":"Tramitando em Conjunto","tr":"Aprovação de Urgência (154, 155 ou 64 CF)","u":"2024-11-12","ds":"Alteração do Regime de Tramitação desta proposição em virtude da alteração do regime do PL 212/2024, por ter sido aprovado o REQ 486/2024 que está apensado ao primeiro.","id":"2417888","law":false,"r":"m"},{"t":"PL","n":"227","y":"2024","e":"Altera dispositivos da Lei nº 10.826, de 22 de dezembro de 2003, e da Lei nº 8.906, de 4 de julho de 1994, para conferir aos advogados a prerrogativa do porte de arma de fogo para defesa pessoal e dá outras providências.","d":"2024-02-08","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apresentação de Requerimento","u":"2024-05-27","ds":"Apresentação do REQ n. 1802/2024 (Requerimento de Desapensação), pelos Deputados Carla Zambelli (PL/SP) e Sargento Gonçalves PL, que \"Requer a desapensação do Projeto de Lei nº 227, de 2024, do Projeto de Lei nº 3.722, de 2012\".","id":"2417672","law":false,"r":"m"},{"t":"PL","n":"214","y":"2024","e":"Institui o Dia Nacional dos Presos Políticos.","d":"2024-02-07","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2024-02-26","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 27/02/2024 PAG 130","id":"2417644","law":false,"r":"c"},{"t":"PL","n":"158","y":"2024","e":"Inclui o inciso XII no artigo 6º da Lei nº 10.826 de 2003, para conceder o porte de arma aos vigilantes e dá outras providências.","d":"2024-02-06","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2024-02-21","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 22/02/2024.","id":"2417308","law":false,"r":"m"},{"t":"PL","n":"98","y":"2024","e":"Altera o Decreto Lei nº 2.848 de 07 de Dezembro de 1940, de abril de 2019 (Código Penal Brasileiro), para estabelecer o aumento de pena na conduta tipificada Denunciação Caluniosa que envolva ambiente familiar de coabitação.","d":"2024-02-05","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Despacho","u":"2024-02-27","ds":"Deferido o REQ 397/2024.","id":"2417059","law":false,"r":"c"},{"t":"PDL","n":"559","y":"2023","e":"Susta a Resolução nº 2, de 23 de novembro de 2023, do Comitê Gestor de Indicadores e Níveis de Eficiência Energética, do Ministério de Minas e Energia, que veda a fabricação, importação e comercialização de refrigeradores e congeladores com preços mais acessíveis à população.","d":"2023-12-21","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2026-06-09","ds":"Devolvido ao Relator, Dep. Clodoaldo Magalhães (PV-PE), para o PDL 488/2023, ao qual esta proposição está apensada.","id":"2416195","law":false,"r":"c"},{"t":"PL","n":"5967","y":"2023","e":"Acrescenta os parágrafos 1º a 5º ao art. 24 do Decreto-Lei nº 667, de 2 de julho de 1969, para assegurar aos policiais militares e bombeiros militares a carga horária de 144 horas mensais, bem como a remuneração extraordinária no trabalho realizado que extrapole a carga horária vigente, remuneração em dobro nos feriados e dá outras providências.","d":"2023-12-12","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2026-05-04","ds":"Remessa ao Senado Federal por meio do Of. nº 102/2026/SGM-P.","id":"2412181","law":false,"r":"c"},{"t":"PL","n":"5793","y":"2023","e":"Altera os artigos 359-L, 359-M e 359-T da Parte Especial do Decreto-lei nº 2.848, de 7 de dezembro de 1940 (Código Penal), bem como o art. 79 do  Decreto-Lei nº 3.689, de 3 de outubro de 1941 (Código de Processo Penal), e dá outras providências.","d":"2023-11-30","o":"approved_with_another_bill","s":"Arquivada","tr":"Prejudicialidade (Plenário)","u":"2025-12-09","ds":"Matéria aprovada na forma do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão). Esta proposição fica prejudicada, na forma do art. 191 do RICD.","id":"2408580","law":false,"r":"c"},{"t":"PEC","n":"64","y":"2023","e":"Altera  disposições  sobre  servidores policiais, para dispor sobre seu Regime Jurídico Policial.","d":"2023-11-24","o":"in_progress","s":"Aguardando Despacho do Presidente da Câmara dos Deputados (Chancela)","tr":"Relatório de Conferência de Assinaturas","u":"2023-11-24","ds":"Relatório de Conferência de Assinaturas Eletrônicas.","id":"2406638","law":false,"r":"c"},{"t":"PDL","n":"406","y":"2023","e":"Susta a Portaria MTE nº 3.665, de 13 de novembro de 2023, do Ministério do Trabalho e Emprego, que altera a Portaria/MTP nº 671, de 8 de novembro de 2021. (Processo nº 19964.203605/2023-95)","d":"2023-11-16","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-12-19","ds":"Designado Relator, Dep. Joaquim Passarinho (PL-PA), para o PDL 405/2023, ao qual esta proposição está apensada.","id":"2403924","law":false,"r":"c"},{"t":"PDL","n":"398","y":"2023","e":"Susta o DECRETO Nº 11.768, DE 6 DE NOVEMBRO DE 2023, que autoriza a reversão do processo de dissolução societária da empresa pública Centro Nacional de Tecnologia Eletrônica Avançada S.A. - Ceitec.","d":"2023-11-08","o":"status_not_published","s":"","tr":"Notificacao para Publicação Intermediária","u":"2026-03-05","ds":"Designado Relator, Dep. Zé Adriano (PP-AC), para o PDL 397/2023, ao qual esta proposição está apensada.","id":"2402828","law":false,"r":"c"},{"t":"PDL","n":"392","y":"2023","e":"Susta o Decreto nº 11.764, de 31 de outubro de 2023, que altera a Tabela de Incidência do Imposto sobre Produtos Industrializados - TIPI, aprovada pelo Decreto nº 11.158, de 29 de julho de 2022.","d":"2023-11-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Publicação de Proposição","u":"2023-11-07","ds":"Encaminhada à publicação. Publicação Inicial em avulso e no DCD de 08/11/2023.","id":"2401109","law":false,"r":"c"},{"t":"PL","n":"5021","y":"2023","e":"Institui a Lista de Organizações Terroristas, altera a Lei nº 13.260, de 16 de março de 2016, e dá outras providências.","d":"2023-10-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-07-07","ds":"Apensação da proposição PL 2730/2026 à proposição PL 972/2024.","id":"2396351","law":false,"r":"c"},{"t":"PL","n":"4894","y":"2023","e":"Dispõe sobre sanções políticas e econômicas relacionadas ao Hamas e ao Hezbollah, os classifica como grupos terroristas, e criminaliza manifestações de apoio a esses grupos.","d":"2023-10-09","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-10-14","ds":"Designada Relatora, Dep. Carla Dickson (PL-RN).","id":"2394641","law":false,"r":"c"},{"t":"PL","n":"4789","y":"2023","e":"Altera o Decreto-Lei nº 2.848, de 7 de dezembro de 1940 - Código Penal, a Lei nº 8.069, de 13 de julho de 1990 - Estatuto da Criança e do Adolescente, a Lei nº 8.072, de 25 de julho de 1990 - Lei de Crimes Hediondos, a Lei nº 7.210, de 11 de julho de 1984 - Lei de Execução Penal, e o Decreto Lei nº 3.689, de 3 de outubro de 1941 - Código de Processo Penal, para recrudescer o tratamento penal destinado aos crimes sexuais contra crianças e adolescentes, visando prevenir e coibir o incentivo à pedofilia.","d":"2023-10-03","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-05-21","ds":"Parecer do Relator, Dep. Filipe Martins (PL-TO), pela aprovação do PL 4789/23, do PLs 20/24,1978/24, 3920/25, 4061/25, e 1201/26, apensados, com substitutivo.","id":"2392485","law":false,"r":"c"},{"t":"PDL","n":"337","y":"2023","e":"Susta a Resolução n° 2, de 19 de setembro de 2023, do Conselho Nacional dos Direitos das Pessoas Lésbicas, Gays, Bissexuais, Travestis, Trans., Queers, Intersexos.","d":"2023-09-25","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-07-30","ds":"Designado Relator, Dep. Daniel José (PODE-SP), para o PDL 335/2023, ao qual esta proposição está apensada.","id":"2390075","law":false,"r":"c"},{"t":"PEC","n":"44","y":"2023","e":"Adiciona-se parágrafo 9ºB ao artigo 166 da Constituição Federal para permitir o emendamento em reserva, de 5% para o uso em catástrofes e emergências naturais.\n\n\n\n\nNOVA EMENTA: Altera o art. 166 da Constituição Federal e acrescenta o art. 138 no Ato das Disposições Constitucionais Transitórias, para destinar parte dos recursos das emendas individuais e de bancadas estaduais e do orçamento da União a ações de prevenção, mitigação, preparação, resposta e recuperação de desastres.","d":"2023-09-14","o":"approved","s":"Aguardando Apreciação pelo Senado Federal","tr":"Expedição de Documento","u":"2024-07-16","ds":"Remessa ao Senado Federal por meio do Of. nº 115/2024/SGM-P.","id":"2388029","law":false,"r":"c"},{"t":"PL","n":"4066","y":"2023","e":"Institui a Semana Nacional da Cultura Evangélica, a ser celebrada anualmente na segunda semana de dezembro, promovendo a integração entre instituições religiosas evangélicas, eventos culturais e a valorização da diversidade religiosa em todo o território nacional.","d":"2023-08-22","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-22","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 23/09/2023.","id":"2381586","law":false,"r":"m"},{"t":"PL","n":"3977","y":"2023","e":"Altera a Lei nº 7.102, de 20 de junho de 1983, para incluir o inciso V no Art. 19, tornando obrigatório o uso de colete de proteção balística nível III-A por vigilantes, e dá nova redação ao art. 22 e seu parágrafo único para ampliar o rol de equipamentos em uso por estes durante a prestação do serviço de vigilância.","d":"2023-08-17","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2023-08-30","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 31/08/2023.","id":"2380506","law":false,"r":"m"},{"t":"PDL","n":"262","y":"2023","e":"Susta a Resolução CONAC-MPOR nº 1, de 10 agosto de 2023.","d":"2023-08-16","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2024-05-22","ds":"Designado Relator, Dep. Gutemberg Reis (MDB-RJ)","id":"2379900","law":false,"r":"c"},{"t":"PEC","n":"34","y":"2023","e":"Inclui dispositivos nos artigos 3º e 5º da Constituição da República Federativa do Brasil, estabelecendo o combate às drogas ilícitas como princípio fundamental e vedando expressamente a descriminalização do tráfico e a legalização de novas drogas recreativas.","d":"2023-08-09","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-02-10","ds":"(Instalação da Comissão) A Relatora, Dep. Caroline de Toni, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2377463","law":false,"r":"m"},{"t":"PDL","n":"214","y":"2023","e":"Susta o Decreto nº 11.629, de 2023, nos termos do art. 49, V da Constituição Federal.","d":"2023-08-08","o":"in_progress","s":"Aguardando Parecer","tr":"Designação de Relator(a)","u":"2026-04-15","ds":"Designado Relator, Dep. Rubens Otoni (PT-GO).","id":"2376477","law":false,"r":"c"},{"t":"PL","n":"3763","y":"2023","e":"Dispõe sobre a criação de Delegacias Especializadas em Conflitos Agrários.","d":"2023-08-07","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Publicação de Proposição","u":"2024-12-11","ds":"Encaminhada à publicação. Parecer da Comissão de Segurança Pública e Combate ao Crime Organizado Publicado em avulso e no DCD de 12/12/2024 PÁG 1907, Letra B.","id":"2376039","law":false,"r":"c"},{"t":"PDL","n":"209","y":"2023","e":"Susta os efeitos da Resolução nº 510, de 26 de junho de 2023, do Conselho Nacional de Justiça, que “regulamenta a criação, no âmbito do Conselho Nacional de Justiça e dos Tribunais, respectivamente, da Comissão Nacional de Soluções Fundiárias e das Comissões Regionais de Soluções Fundiárias, institui diretrizes para a realização de visitas técnicas nas áreas objeto de litígio possessório e estabelece protocolos para o tratamento das ações que envolvam despejos ou reintegrações de posse em imóveis de moradia coletiva ou de área produtiva de populações vulneráveis”.","d":"2023-08-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2025-03-14","ds":"Recebimento pela CCJC, apensado ao PDL-182/2023","id":"2375447","law":false,"r":"c"},{"t":"PDL","n":"204","y":"2023","e":"Susta parte dos efeitos do DECRETO Nº 6.286, DE 5 DE DEZEMBRO DE 2007, que institui o Programa Saúde na Escola - PSE, e dá outras providências.","d":"2023-08-01","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2025-11-05","ds":"Parecer da Relatora, Dep. Ana Paula Lima (PT-SC), pela rejeição.","id":"2374905","law":false,"r":"c"},{"t":"PDL","n":"198","y":"2023","e":"Susta os efeitos da Resolução nº 715, de 20 de julho de 2023, do Conselho Nacional de Saúde, que trata das “orientações estratégicas para o Plano Plurianual (PPA) e para o Plano Nacional de Saúde (PNS) 2024-2027”.","d":"2023-07-28","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-28","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 29/09/2023.","id":"2374503","law":false,"r":"c"},{"t":"PDL","n":"189","y":"2023","e":"Susta o Decreto nº 11.615, de 21 de julho de 2023, que regulamenta a Lei nº 10.826, de 22 de dezembro de 2003, para estabelecer regras e procedimentos relativos à aquisição, ao registro, à posse, ao porte, ao cadastro e à comercialização nacional de armas de fogo, munições e acessórios, disciplinar as atividades de caça excepcional, de caça de subsistência, de tiro desportivo e de colecionamento de armas de fogo, munições e acessórios, disciplinar o funcionamento das entidades de tiro desportivo e dispor sobre a estruturação do Sistema Nacional de Armas - Sinarm.","d":"2023-07-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP), para o PDL 3/2023, ao qual esta proposição está apensada.","id":"2374340","law":false,"r":"c"},{"t":"PDL","n":"186","y":"2023","e":"Susta os efeitos do Decreto nº 11.611, de 19 de Julho 2023, que revoga o Decreto nº 10.004, de 5 de setembro de 2019, que institui o Programa Nacional das Escolas Cívico-Militares.","d":"2023-07-21","o":"returned_to_author","s":"Devolvida ao(à) Autor(a)","tr":"Publicação de Proposição","u":"2023-09-28","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 29/09/2023.","id":"2374328","law":false,"r":"c"},{"t":"PLP","n":"141","y":"2023","e":"Altera o inciso XIV do artigo 22, da Lei Complementar nº 64, de 18 de maio de 1990, para determinar que a sanção de inelegibilidade para as eleições a se realizarem seja nos 2 (dois) anos subsequentes à eleição.","d":"2023-07-04","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2025-06-11","ds":"Deferido o REQ 678/2025.","id":"2372482","law":false,"r":"c"},{"t":"PL","n":"3317","y":"2023","e":"Concede anistia aos condenados por ilícitos cíveis eleitorais ou declarados inelegíveis do período de 2 de outubro 2016 até a data de entrada em vigor desta lei, na forma que especifica.","d":"2023-06-30","o":"prejudged","s":"Arquivada","tr":"Desapensação","u":"2025-12-09","ds":"Desapensação deste do PL nº 2.162, de 2023, principal, em face da aprovação, em Plenário, do Substitutivo ao Projeto de Lei nº 2.162, de 2023, adotado pelo relator da Comissão Especial. (Sessão Deliberativa Extraordinária Presencial de 09/12/2025 - 19:00 - 278ª Sessão)","id":"2372030","law":false,"r":"c"},{"t":"PL","n":"3269","y":"2023","e":"Regulamenta os direitos dos membros dos órgãos de segurança pública quando atuantes como condutores de ocorrências que resultaram em prisões, assegurando prerrogativas especiais em audiências e depoimentos no processo criminal.","d":"2023-06-27","o":"in_progress","s":"Tramitando em Conjunto","tr":"Apresentação de Requerimento","u":"2024-07-02","ds":"Apresentação do REQ n. 2453/2024 (Requerimento de Desapensação), pelo Deputado Sargento Gonçalves (PL/RN), que \"Requer a desapensação do Projeto de Lei nº 3269, de 2023, do Projeto de Lei nº 8045, de 2010\".","id":"2371572","law":false,"r":"m"},{"t":"PL","n":"3142","y":"2023","e":"Altera o Código Penal, para dispor sobre a tipificação do crime de permissão de ingresso de ditador em território nacional.","d":"2023-06-19","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2024-10-07","ds":"Parecer da Relatora, Dep. Julia Zanatta (PL-SC), pela constitucionalidade, juridicidade, técnica legislativa e, no mérito, pela aprovação.","id":"2370152","law":false,"r":"c"},{"t":"PL","n":"2927","y":"2023","e":"Altera a lei 9.503 de 23 de setembro 1997, que institui o Código de Trânsito Brasileiro, inserindo o art. 44-B e parágrafo único no Art. 208, a fim de regulamentar a possibilidade dos condutores de veículos avançarem o sinal vermelho com ou sem monitoramento entre o horário das 23h (vinte e três) e 5h (cinco) horas da manhã com velocidade máxima de até 30 Km/h.","d":"2023-06-02","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-03-04","ds":"Designado Relator, Dep. Aureo Ribeiro (SOLIDARI-RJ), para o PL 8085/2014, ao qual esta proposição está apensada.","id":"2367425","law":false,"r":"m"},{"t":"PL","n":"2606","y":"2023","e":"Institui a identificação biométrica e ou facial para ingresso nas escolas da rede pública ou privada da educação básica de ensino, a submissão dos ingressantes à verificação por equipamentos detectores de metais e sobre a obrigatoriedade de aquisição de equipamentos de detecção de metais, porta giratória com detecção de metais e outros equipamentos.","d":"2023-05-16","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificações","u":"2024-12-09","ds":"Designada Relatora, Dep. Duda Salabert (PDT-MG), para o PL 5343/2019, ao qual esta proposição está apensada.","id":"2362562","law":false,"r":"m"},{"t":"PDL","n":"153","y":"2023","e":"Susta os efeitos da Resolução n. 487, de 15 de fevereiro de 2023, do Conselho Nacional de Justiça, que “institui a Política Antimanicomial do Poder Judiciário e estabelece procedimentos e diretrizes para implementar a Convenção Internacional dos Direitos das Pessoas com Deficiência e a Lei n. 10.216/2001, no âmbito do processo penal e da execução das medidas de segurança”.","d":"2023-05-16","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-05-24","ds":"Recebimento pela CCJC, apensado ao PDL-81/2023","id":"2362328","law":false,"r":"c"},{"t":"PL","n":"2568","y":"2023","e":"Veda a utilização de dinheiro público em quaisquer eventos e serviços que promovam a erotização precoce ou estimulem a sexualização de crianças e adolescentes.","d":"2023-05-15","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificação de Apensação","u":"2026-07-08","ds":"Apensação do PL 2654/2026 a esta proposição.","id":"2362236","law":false,"r":"c"},{"t":"PL","n":"2501","y":"2023","e":"Dispõe sobre a criação do crime de censura e confisco de plataforma na lei 13.869 de 5 de setembro de 2019, que dispõe sobre os crimes de abuso de autoridade, e adiciona o crime de censura na lei 1.079 de 10 de abril de 1950, que dispõe sobre os crimes de responsabilidade, e dá outras providências.","d":"2023-05-10","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-10-15","ds":"Designado Relator, Dep. Pr. Marco Feliciano (PL-SP), para o PL 2782/2022, ao qual esta proposição está apensada.","id":"2361794","law":false,"r":"c"},{"t":"PL","n":"2155","y":"2023","e":"Altera a redação do artigo 6º da lei 10.826 de 2003, para conceder o porte de arma aos professores.","d":"2023-04-26","o":"in_progress","s":"Tramitando em Conjunto","tr":"Recebimento","u":"2023-06-16","ds":"Recebimento pela CE.","id":"2358497","law":false,"r":"m"},{"t":"PDL","n":"128","y":"2023","e":"Susta a Portaria nº 351/2023, do Ministério da Justiça e Segurança Pública, que dispõe sobre medidas administrativas a serem adotadas no âmbito do Ministério da Justiça e Segurança Pública, para fins de prevenção à disseminação de conteúdos flagrantemente ilícitos, prejudiciais ou danosos por plataformas de redes sociais, e dá outras providências.","d":"2023-04-17","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-05-07","ds":"Designado Relator, Dep. Juscelino Filho (PSDB-MA), para o PDL 122/2023, ao qual esta proposição está apensada.","id":"2356597","law":false,"r":"c"},{"t":"PL","n":"1881","y":"2023","e":"Estabelece que a cobrança, pela União, de tarifas, taxas e dos custos operacionais e de manutenção de obras ou serviços públicos vinculados ao aproveitamento econômico e social dos rios e das massas de água, nas regiões de secas periódicas, respeitará o prazo de carência de 5 (cinco) anos da entrada em operação do empreendimento, e altera a Lei nº 14.182, de 12 de julho de 2021, que dispõe sobre a desestatização da empresa Centrais Elétricas Brasileiras S.A. (Eletrobras).","d":"2023-04-13","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-04-17","ds":"Prazo de Vista Encerrado","id":"2356291","law":false,"r":"c"},{"t":"PL","n":"1517","y":"2023","e":"Altera a redação do artigo 2º, inclui o inciso IV no §1º e insere o §3º no art. 2º da Lei 13.260, de 16 de março de 2016, com a finalidade de figurar em seu rol os atos praticados por organizações criminosas.","d":"2023-03-29","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Retirada pelo(a) Autor(a)","u":"2024-07-02","ds":"Retirado o PL n. 1517/2023, em razão do deferimento do Requerimento n. REQ 1768/2024, nos termos do artigo 104, caput, combinado com o artigo 114, VII, ambos do RICD.","id":"2354147","law":false,"r":"m"},{"t":"PL","n":"1110","y":"2023","e":"Insere o inciso XIII e o § 5º na Lei n.º 13.756, de 12 de dezembro de 2018, para destinar recursos do Fundo Nacional de Segurança Pública (FNSP) para criar programas de bolsa de estudo aos dependentes de policiais militares e bombeiros militares que faleceram no exercício da profissão ou em razão dela.","d":"2023-03-14","o":"in_progress","s":"Aguardando Designação de Relator(a)","tr":"Saída de Relator(a) da Comissão - Com Parecer Apresentado","u":"2026-03-19","ds":"(Instalação da Comissão) O Relator, Dep. Sargento Portugal, não integrava a Comissão na data da instalação (deixou de ser membro em 31/01/2026)","id":"2351252","law":false,"r":"m"},{"t":"PL","n":"942","y":"2023","e":"Estabelece a isenção de taxa de renovação e demais exames necessários à renovação da Carteira Nacional de Habilitação aos profissionais condutores de veículos de urgência públicos.","d":"2023-03-07","o":"in_progress","s":"Pronta para Pauta","tr":"Encerramento de Prazo","u":"2026-09-01","ds":"Encerrado o prazo de 5 sessões para apresentação de emendas ao substitutivo (de 04/08/2026 a 01/09/2026). Não foram apresentadas emendas ao substitutivo.","id":"2350381","law":false,"r":"c"},{"t":"PL","n":"771","y":"2023","e":"Altera a Lei nº 9.394, de 20 de dezembro de 1996, a Lei nº 13.869, de 5 de setembro de 2019 e dá outras providências.","d":"2023-03-01","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-03-16","ds":"Designado Relator, Dep. Capitão Alden (PL-BA), para o PL 5198/2020, ao qual esta proposição está apensada.","id":"2349738","law":false,"r":"m"},{"t":"PL","n":"757","y":"2023","e":"Altera a Lei nº 9.394, de 20 de dezembro de 1996 e a Lei nº 13.869, de 5 de setembro de 2019 e dá outras providências.","d":"2023-03-01","o":"withdrawn","s":"Retirado pelo(a) Autor(a)","tr":"Publicação de Proposição","u":"2023-04-24","ds":"Encaminhada à publicação. Publicação Inicial no DCD de 25/04/2023 PAG 261","id":"2349667","law":false,"r":"m"},{"t":"PL","n":"607","y":"2023","e":"INSERE  NA LEI N.º 9.503, DE 23 DE SETEMBRO 1997, O ART. 106-A.","d":"2023-02-22","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2026-04-16","ds":"Designado Relator, Dep. Julio Arcoverde (PP-PI), para o PL 982/2022, ao qual esta proposição está apensada.","id":"2349043","law":false,"r":"m"},{"t":"PL","n":"606","y":"2023","e":"Estabelece tratamento isonômico entre agentes públicos e políticos na fiscalização  de sua atividade pública por meio de  vídeomonitoramento individual enquanto no  exercício da função.","d":"2023-02-22","o":"in_progress","s":"Pronta para Pauta","tr":"Parecer do(a) Relator(a)","u":"2026-03-26","ds":"Parecer do Relator, Dep. Capitão Alden (PL-BA), pela aprovação.","id":"2349042","law":false,"r":"m"},{"t":"PL","n":"269","y":"2023","e":"Dispõe sobre a proibição de bloqueio puberal hormonal em crianças e adolescentes em processo transexualizador e de terapia hormonal e cirurgia de redesignação sexual, respectivamente a menores de 18 e 21 anos.","d":"2023-02-03","o":"in_progress","s":"Tramitando em Conjunto","tr":"Notificacao para Publicação Intermediária","u":"2025-12-18","ds":"Designada Relatora, Dep. Talíria Petrone (PSOL-RJ), para o PL 3419/2019, ao qual esta proposição está apensada.","id":"2347069","law":false,"r":"c"},{"t":"PDL","n":"3","y":"2023","e":"Susta o Decreto nº 11.366, de 1º de janeiro 2023, que limita o registro e a aquisição de armas de fogos.","d":"2023-02-02","o":"in_progress","s":"Aguardando Parecer","tr":"Devolução ao(à) Relator(a)","u":"2025-04-14","ds":"Devolvido ao Relator, Dep. Delegado Paulo Bilynskyj (PL-SP)","id":"2345680","law":false,"r":"c"}];
